module fluttershy_scheduling(input clk, input rst_n, input start, input [31:0] config_p_in [0:3], input [31:0] config_r_in [0:3], input [4:0] customer_type_in, input [31:0] customer_time_in, input in_valid, output reg in_ready, output reg [31:0] result, output reg result_valid); localparam M = 4; localparam INF = 32'd 0xFFFFFFFF; reg [31:0] dp_state [0:M]; reg [15:0] served_counter; reg [15:0] customer_counter; reg [2:0] state; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= 0; served_counter <= 0; customer_counter <= 0; dp_state[0] <= INF; dp_state[1] <= INF; dp_state[2] <= INF; dp_state[3] <= INF; dp_state[4] <= 0; end else begin if (state == 0) begin if (start) begin state <= 1; dp_state[0] <= INF; dp_state[1] <= INF; dp_state[2] <= INF; dp_state[3] <= INF; dp_state[4] <= 0; served_counter <= 0; customer_counter <= 0; end end end end end assign in_ready = (state == 1) && (customer_counter < 16); always @(posedge clk or negedge rst_n) begin if (!rst_n) begin // Reset handling already done end else begin if (state == 1) begin if (in_valid && in_ready && customer_counter < 16) begin served_counter <= served_counter + 1; customer_counter <= customer_counter + 1; if (customer_counter == 16) begin state <= 2; end end end end end end assign result_valid = (state == 2); assign result = served_counter; endmodule